decoration\";s:4:\"none\";s:11:\"strokecolor\";s:7:\"#000000\";s:6:\"cursor\";s:7:\"pointer\";}'),(2364,263,'_ec_chart_bar','a:5:{s:10:\"fontfamily\";s:5:\"Arial\";s:8:\"fontsize\";s:2:\"10\";s:10:\"fontweight\";s:3:\"700\";s:11:\"strokecolor\";s:4:\"none\";s:9:\"textcolor\";s:7:\"#000000\";}'),(2365,263,'_ec_chart_line','a:1:{s:13:\"interpolation\";s:6:\"linear\";}'),(2366,263,'_ec_chart_area','a:3:{s:13:\"interpolation\";s:6:\"linear\";s:7:\"opacity\";d:0.2;s:6:\"offset\";s:4:\"zero\";}'),(2367,263,'_ec_chart_pie','a:7:{s:10:\"fontfamily\";s:5:\"Arial\";s:8:\"fontsize\";s:2:\"11\";s:10:\"fontweight\";s:3:\"700\";s:11:\"fontvariant\";s:10:\"small-caps\";s:8:\"fontfill\";s:7:\"#000000\";s:11:\"strokecolor\";s:7:\"#ffffff\";s:11:\"strokewidth\";s:1:\"1\";}'),(2368,263,'_ec_chart_donut','a:8:{s:10:\"fontfamily\";s:5:\"Arial\";s:8:\"fontsize\";s:2:\"11\";s:10:\"fontweight\";s:3:\"700\";s:11:\"fontvariant\";s:10:\"small-caps\";s:8:\"fontfill\";s:7:\"#000000\";s:11:\"strokecolor\";s:7:\"#ffffff\";s:11:\"strokewidth\";s:1:\"1\";s:6:\"factor\";s:3:\"0.4\";}'),(2421,276,'_wp_attached_file','rubis-energie-distribution-pays-1.jpg'),(2422,276,'_wp_attachment_metadata','a:5:{s:5:\"width\";i:580;s:6:\"height\";i:359;s:4:\"file\";s:37:\"rubis-energie-distribution-pays-1.jpg\";s:5:\"sizes\";a:2:{s:6:\"medium\";a:4:{s:4:\"file\";s:45:\"rubis-energie-distribution-pays-1-300x186.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:186;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:9:\"thumbnail\";a:4:{s:4:\"file\";s:45:\"rubis-energie-distribution-pays-1-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"1\";s:8:\"keywords\";a:0:{}}}'),(2426,279,'_wp_attached_file','rubis-energie-support-services-pays.jpg'),(2427,279,'_wp_attachment_metadata','a:5:{s:5:\"width\";i:580;s:6:\"height\";i:359;s:4:\"file\";s:39:\"rubis-energie-support-services-pays.jpg\";s:5:\"sizes\";a:2:{s:6:\"medium\";a:4:{s:4:\"file\";s:47:\"rubis-energie-support-services-pays-300x186.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:186;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:9:\"thumbnail\";a:4:{s:4:\"file\";s:47:\"rubis-energie-support-services-pays-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(2430,162,'form_fields_6_fields_placeholder','Message *'),(2431,162,'_form_fields_6_fields_placeholder','field_5d1dc31496fab'),(2434,162,'form_fields_7_fields_name','document'),(2435,162,'_form_fields_7_fields_name','field_5df0bec43f327'),(2436,162,'form_fields_7_fields_multiple_choice','0'),(2437,162,'_form_fields_7_fields_multiple_choice','field_5d7f4509278f7'),(2438,162,'form_fields_7_fields_label','Autre document'),(2439,162,'_form_fields_7_fields_label','field_5df0bed03f328'),(2440,162,'form_fields_7_fields_required','0'),(2441,162,'_form_fields_7_fields_required','field_5df0bee53f329'),(2471,285,'_wp_attached_file','rubis-energie-support-services-3.jpg'),(2472,285,'_wp_attachment_metadata','a:5:{s:5:\"width\";i:1179;s:6:\"height\";i:400;s:4:\"file\";s:36:\"rubis-energie-support-services-3.jpg\";s:5:\"sizes\";a:4:{s:6:\"medium\";a:4:{s:4:\"file\";s:44:\"rubis-energie-support-services-3-300x102.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:102;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:5:\"large\";a:4:{s:4:\"file\";s:45:\"rubis-energie-support-services-3-1024x347.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:347;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:9:\"thumbnail\";a:4:{s:4:\"file\";s:44:\"rubis-energie-support-services-3-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:12:\"medium_large\";a:4:{s:4:\"file\";s:44:\"rubis-energie-support-services-3-768x261.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:261;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:3:\"2.8\";s:6:\"credit\";s:14:\"GILLES DACQUIN\";s:6:\"camera\";s:9:\"NIKON D4S\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:10:\"1478519280\";s:9:\"copyright\";s:14:\"GILLES DACQUIN\";s:12:\"focal_length\";s:2:\"58\";s:3:\"iso\";s:3:\"400\";s:13:\"shutter_speed\";s:6:\"0.0005\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"1\";s:8:\"keywords\";a:0:{}}}'),(2473,69,'block_4_fields_slider_2_image','870'),(2474,69,'_block_4_fields_slider_2_image','field_5d31be18faf3f'),(2475,79,'block_4_fields_title','Nos actualités pour le changement climatique'),(2476,79,'_block_4_fields_title','field_60dac2d72dc34'),(2477,79,'block_4_fields_link','a:3:{s:5:\"title\";s:15:\"Nos actualités\";s:3:\"url\";s:40:\"https://www.rubisenergie.com/actualites/\";s:6:\"target\";s:0:\"\";}'),(2478,79,'_block_4_fields_link','field_60dac2df2dc35'),(2479,79,'block_4_fields_actus','a:3:{i:0;s:2:\"55\";i:1;s:3:\"210\";i:2;s:2:\"58\";}'),(2480,79,'_block_4_fields_actus','field_60dac2e52dc36'),(2483,79,'block_5_fields_text','Outre la réduction des émissions de CO2, chaque projet mené dans ces Départements Français d’Amérique (DFA) vise le développement de l’emploi, des compétences de tous niveaux. La SARA est également un des principaux contributeurs à l’émergence de techniques et d’entreprises s’attaquant au problème des sargasses, de la chlordécone.\r\n\r\n&nbsp;\r\n<h3></h3>\r\n<h3>Channel Islands</h3>\r\n<ul>\r\n 	<li>Distribution de l’HVO (Hydrotreated Vegetable Oil) : un diesel pour un avenir plus vert, le RD100. Nous fournissons désormais le RD100 dans toutes nos stations-service de Guernesey.</li>\r\n</ul>\r\n<img class=\"size-medium wp-image-747 aligncenter\" src=\"https://www.rubisenergie.com/uploads/HVO-RD100-300x118.jpg\" alt=\"\" width=\"300\" height=\"118\" />\r\n\r\n&nbsp;\r\n\r\n<hr />\r\n\r\n&nbsp;'),(2484,79,'_block_5_fields_text','field_5d318356707db'),(2487,79,'block_6_fields_first_col','<img class=\"alignnone size-full wp-image-218 aligncenter\" src=\"https://www.rubisenergie.com/uploads/rubis-energie-garantie-securite.jpg\" alt=\"\" width=\"960\" height=\"640\" />\r\n<p style=\"text-align: center;\"><strong>Garantir la sécurité et</strong>\r\n<strong>Préserver l’environnement</strong></p>\r\n<p style=\"text-align: center;\"><span style=\"text-decoration: underline;\"><a class=\"cta green\" href=\"https://www.rubisenergie.com/engagements/garantir-securite-preserver-environnement/\">en savoir plus</a></span></p>'),(2488,79,'_block_6_fields_first_col','field_60dac1ad921d3'),(2489,79,'block_6_fields_second_col','<img class=\"alignnone size-full wp-image-208 aligncenter\" src=\"https://www.rubisenergie.com/uploads/rubis-energie-engagements-employabilite.jpg\" alt=\"\" width=\"960\" height=\"640\" />\r\n<p style=\"text-align: center;\"><strong>S’engager pour</strong>\r\n<strong>l’employabilité</strong></p>\r\n<p style=\"text-align: center;\"><span style=\"text-decoration: underline;\"><a class=\"cta green\" href=\"https://www.rubisenergie.com/engagements/employabilite/\">en savoir plus</a></span></p>'),(2490,79,'_block_6_fields_second_col','field_60dac1c1921d4'),(2491,79,'block_6_fields_third_col','<img class=\"alignnone size-full wp-image-296 aligncenter\" src=\"https://www.rubisenergie.com/uploads/rubis-energie-agir-ethique-societale.jpg\" alt=\"\" width=\"960\" height=\"649\" />\r\n<p style=\"text-align: center;\"><strong>Agir de manière\r\néthique et sociétale</strong></p>\r\n<p style=\"text-align: center;\"><span style=\"text-decoration: underline;\"><a class=\"cta green\" href=\"https://www.rubisenergie.com/engagements/agir-ethique-societale/\">en savoir plus</a></span></p>'),(2492,79,'_block_6_fields_third_col','field_60dac1cf921d5'),(2495,286,'_edit_last','2'),(2496,286,'_edit_lock','1694767544:2'),(2497,286,'_wp_page_template','tpl/history.tpl.php'),(2498,286,'header_page_text','Le Groupe, qui mène depuis 25 ans une politique volontariste d’investissements et de développement dans ses métiers, est présent aujourd’hui dans 41 pays.'),(2499,286,'_header_page_text','field_60dad748a56be'),(2500,286,'header_page_color','#4a58c1'),(2501,286,'_header_page_color','field_60dad74ca56bf'),(2502,286,'header_page_img','295'),(2503,286,'_header_page_img','field_60dad753a56c0'),(2504,286,'header_page',''),(2505,286,'_header_page','field_60dad72fa56bc'),(2506,286,'history_text','<h2>Un développement à l’international dès 1997</h2>\r\nA travers une matrice de produits, de marchés et d’offres diversifiées, le Groupe réduit ainsi considérablement son risque global d’exposition.\r\n\r\nA l\'origine exclusivement présent en France métropolitaine, le Groupe amorce, dès 1997, son développement à l\'international. Un développement qui le conduit à conquérir des positions stratégiques à l\'étranger.\r\n\r\n&nbsp;\r\n<h3>Les implantations de Rubis Energie à travers le Monde :</h3>'),(2507,286,'_history_text','field_60ed8a181b38b'),(2508,286,'history_decade_0_decade','1990\'s'),(2509,286,'_history_decade_0_decade','field_60ed8cea1b38d'),(2510,286,'history_decade_0_each_year_0_year',''),(2511,286,'_history_decade_0_each_year_0_year','field_60ed8d1d1b38f'),(2512,286,'history_decade_0_each_year_0_countries_0_each_country','France'),(2513,286,'_history_decade_0_each_year_0_countries_0_each_country','field_60ed8d5f1b391'),(2514,286,'history_decade_0_each_year_0_countries','1'),(2515,286,'_history_decade_0_each_year_0_countries','field_60ed8d3a1b390'),(2516,286,'history_decade_0_each_year_1_year','1997'),(2517,286,'_history_decade